code.cpp:
#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    char c;
    cin >> c;

    if (c >= 'A' && c <= 'Z') {
        cout << "upper" << endl;
    } else if (c >= 'a' && c <= 'z') {
        cout << "lower" << endl;
    } else if (c >= '0' && c <= '9') {
        cout << "digit" << endl;
    } else {
        cout << "other" << endl;
    }

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        char c = sc.next().charAt(0);

        if (c >= 'A' && c <= 'Z') {
            System.out.println("upper");
        } else if (c >= 'a' && c <= 'z') {
            System.out.println("lower");
        } else if (c >= '0' && c <= '9') {
            System.out.println("digit");
        } else {
            System.out.println("other");
        }
    }
}
